    );
    // Pass CI=true to dev server so it uses non-interactive migrations
    await runCommand(
      `E2E tests${uiMode ? " (UI mode)" : headedMode ? " (headed)" : ""}`,
      testCommand,
      { CI: "true" }
    );
  } catch {
    console.error("❌ E2E test setup failed");
    process.exit(1);
  }
};

main();

