#!/usr/bin/env bun
/**
 * End-to-End test script
 *
 * Orchestrates:
 * 1. Start PostgreSQL via docker compose
 * 2. Run Playwright tests (with optional ui/headed modes)
 *
 * Usage:
 *   bun run e2e              # Run E2E tests normally
 *   bun run e2e --ui        # Run with Playwright UI
 *   bun run e2e --headed    # Run in headed mode (browser visible)
 */

import { $ } from "bun";

const args = process.argv.slice(2);
const uiMode = args.includes("--ui");
const headedMode = args.includes("--headed");

const runCommand = async (label: string, cmd: string[]) => {
  console.log(`\n📋 ${label}...`);
  try {
    await $`${cmd}`;
    console.log(`✅ ${label} complete`);
  } catch {
    console.error(`❌ ${label} failed`);
    process.exit(1);
  }
};

const main = async () => {
  try {
    // Start PostgreSQL
    await runCommand("Starting PostgreSQL for E2E tests", [
      "bash",
      "./scripts/db-start.sh",
    ]);
    console.log("✅ PostgreSQL ready");

    // Run Playwright tests
    const testCommand = ["playwright", "test"];
    if (uiMode) {
      testCommand.push("--ui");
    } else if (headedMode) {
      testCommand.push("--headed");
    }

    // Load DATABASE_URL from .env
    let databaseUrl = process.env.DATABASE_URL;
    if (!databaseUrl) {
      try {
        const envContent = await Bun.file(".env").text();
        const dbLine = envContent.split("\n").find(line => line.startsWith("DATABASE_URL"));
        if (dbLine) {
          databaseUrl = dbLine.split("=")[1].trim().replace(/^["']|["']$/g, "");
        }
      } catch {
        databaseUrl = "postgresql://vamsa:password@localhost:5432/vamsa";
      }
    }

    // Deploy migrations (non-interactive)
    console.log("\n📋 Running Prisma migrations...");
    await $`DATABASE_URL=${databaseUrl} bunx prisma migrate deploy`;
    console.log("✅ Migrations complete");

    console.log(
      `\n📋 Running E2E tests${uiMode ? " (UI mode)" : headedMode ? " (headed)" : ""}...`
    );
    await $`${testCommand}`;
    console.log("✅ E2E tests passed");
  } catch {
    console.error("❌ E2E test setup failed");
    process.exit(1);
  }
};

main();

