import { chromium, FullConfig } from "@playwright/test";
import { PrismaClient, UserRole } from "@prisma/client";
import bcrypt from "bcryptjs";

async function globalSetup(config: FullConfig) {
  console.log("🌍 Running global setup for E2E tests...");

  // Initialize Prisma client
  const prisma = new PrismaClient();

  try {
    // Check if test data already exists
    const existingAdmin = await prisma.user.findUnique({
      where: { email: "admin@family.local" },
    });

    if (existingAdmin) {
      console.log("✅ Test data already exists, skipping seed");
      return;
    }

    console.log("📋 Seeding test data...");

    // Create admin user
    const adminPasswordHash = await bcrypt.hash("admin123", 12);
    await prisma.user.create({
      data: {
        email: "admin@family.local",
        name: "Admin User",
        passwordHash: adminPasswordHash,
        role: UserRole.ADMIN,
        isActive: true,
        mustChangePassword: false,
      },
    });
    console.log("✅ Admin user created");

    // Create member user
    const memberPasswordHash = await bcrypt.hash("member123", 12);
    await prisma.user.create({
      data: {
        email: "member@family.local",
        name: "Member User",
        passwordHash: memberPasswordHash,
        role: UserRole.MEMBER,
        isActive: true,
      },
    });
    console.log("✅ Member user created");

    // Create family settings
    const existingSettings = await prisma.familySettings.findFirst();
    if (!existingSettings) {
      await prisma.familySettings.create({
        data: {
          familyName: "Test Family",
          allowSelfRegistration: true,
          requireApprovalForEdits: true,
        },
      });
      console.log("✅ Family settings created");
    }

    console.log("✅ Global setup completed");
  } catch (error) {
    console.error("❌ Global setup failed:", error);
    throw error;
  } finally {
    await prisma.$disconnect();
  }
}

export default globalSetup;

