// Step 1: Connect to database and check if migrations are needed
const client = new Client({
  connectionString: databaseUrl,
});

try {
  await client.connect();
  console.log("✅ Connected to database");

  // Check if User table exists (simple migration check)
  const tableCheck = await client.query(
    `SELECT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name='User')`
  );

  if (!tableCheck.rows[0].exists) {
    console.log("📋 Applying database migrations via Prisma...");
    try {
      execFileSync("bunx", ["prisma", "migrate", "deploy"], {
        stdio: "inherit",
        env: { ...process.env, DATABASE_URL: databaseUrl },
      });
      console.log("✅ Database migrations applied");
    } catch (error) {
      console.error("⚠️  Prisma migration failed, trying reset...");
      // Try prisma db push as fallback
      try {
        execFileSync("bunx", ["prisma", "db", "push", "--skip-generate"], {
          stdio: "inherit",
          env: { ...process.env, DATABASE_URL: databaseUrl },
        });
        console.log("✅ Database schema pushed");
      } catch (pushError) {
        console.error("❌ Failed to apply migrations:", pushError);
        throw pushError;
      }
    }
  } else {
    console.log("✅ Database already initialized");
  }

  // Check if admin user already exists
  const result = await client.query(
    "SELECT id FROM \"User\" WHERE email = $1 LIMIT 1",
    ["admin@family.local"]
  );

