     7→import { Input } from "@/components/ui/input";
     8→import { Button } from "@/components/ui/button";
     9→import {
    10→  Select,
    11→  SelectContent,
    12→  SelectItem,
    13→  SelectTrigger,
    14→  SelectValue,
    15→} from "@/components/ui/select";
    16→import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
    17→import { Card, CardContent } from "@/components/ui/card";
    18→import { Badge } from "@/components/ui/badge";
    19→import { formatDate, calculateAge, getInitials } from "@/lib/utils";
    20→import type { Person, Relationship } from "@prisma/client";
    21→
    22→type PersonWithRelations = Person & {
    23→  relationshipsFrom: (Relationship & { relatedPerson: Person })[];
    24→  relationshipsTo: (Relationship & { person: Person })[];
    25→};
    26→
    27→interface PeopleListProps {
    28→  persons: PersonWithRelations[];
    29→  total: number;
    30→  page: number;
    31→  totalPages: number;
    32→  search: string;
    33→  status?: string;
    34→  gender?: string;
    35→}
    36→
    37→export function PeopleList({
    38→  persons,
    39→  total: _total,
    40→  page,
    41→  totalPages,
    42→  search,
    43→  status,
    44→  gender,
    45→}: PeopleListProps) {
    46→  const router = useRouter();
    47→  const searchParams = useSearchParams();
    48→  const [searchValue, setSearchValue] = useState(search);
    49→
    50→  const updateParams = useCallback(
    51→    (updates: Record<string, string | null>) => {
    52→      const params = new URLSearchParams(searchParams.toString());
    53→      Object.entries(updates).forEach(([key, value]) => {
    54→        if (value) {
    55→          params.set(key, value);
    56→        } else {
    57→          params.delete(key);
    58→        }
    59→      });
    60→      params.delete("page");
    61→      router.push(`/people?${params.toString()}`);
    62→    },
    63→    [router, searchParams]
    64→  );
    65→
    66→  useEffect(() => {
    67→    const timer = setTimeout(() => {
    68→      if (searchValue !== search) {
    69→        updateParams({ search: searchValue || null });
    70→      }
    71→    }, 300);
    72→    return () => clearTimeout(timer);
    73→  }, [searchValue, search, updateParams]);
    74→
    75→  const clearFilters = () => {
    76→    setSearchValue("");
    77→    router.push("/people");
    78→  };
    79→
    80→  const hasFilters = search || status || gender;
    81→
    82→  const handlePageChange = (newPage: number) => {
    83→    const params = new URLSearchParams(searchParams.toString());
    84→    params.set("page", newPage.toString());
    85→    router.push(`/people?${params.toString()}`);
    86→  };
    87→
    88→  return (
    89→    <div className="space-y-4">
    90→      <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
    91→        <div className="relative flex-1">
    92→          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
    93→          <Input
    94→            placeholder="Search by name..."
    95→            value={searchValue}
    96→            onChange={(e) => setSearchValue(e.target.value)}
    97→            className="pl-10"
    98→          />
    99→        </div>
   100→        <div className="flex gap-2">
   101→          <Select
   102→            value={status || "all"}
   103→            onValueChange={(v) =>
   104→              updateParams({ status: v === "all" ? null : v })
   105→            }
   106→          >
   107→            <SelectTrigger className="w-[130px]">
   108→              <SelectValue placeholder="Status" />
   109→            </SelectTrigger>
   110→            <SelectContent>
   111→              <SelectItem value="all">All</SelectItem>
   112→              <SelectItem value="living">Living</SelectItem>
   113→              <SelectItem value="deceased">Deceased</SelectItem>
   114→            </SelectContent>
   115→          </Select>
   116→          <Select
   117→            value={gender || "all"}
   118→            onValueChange={(v) =>
   119→              updateParams({ gender: v === "all" ? null : v })
   120→            }
   121→          >
   122→            <SelectTrigger className="w-[130px]">
   123→              <SelectValue placeholder="Gender" />
   124→            </SelectTrigger>
   125→            <SelectContent>
   126→              <SelectItem value="all">All</SelectItem>
   127→              <SelectItem value="MALE">Male</SelectItem>
   128→              <SelectItem value="FEMALE">Female</SelectItem>
   129→              <SelectItem value="OTHER">Other</SelectItem>
   130→            </SelectContent>
   131→          </Select>
   132→          {hasFilters && (
   133→            <Button variant="ghost" size="icon" onClick={clearFilters}>
   134→              <X className="h-4 w-4" />
   135→            </Button>
   136→          )}
   137→        </div>
   138→      </div>
   139→
   140→      {hasFilters && (
   141→        <div className="flex flex-wrap gap-2">
   142→          {search && <Badge variant="secondary">Search: {search}</Badge>}
   143→          {status && (
   144→            <Badge variant="secondary">
   145→              {status === "living" ? "Living" : "Deceased"}
   146→            </Badge>
   147→          )}
   148→          {gender && (
   149→            <Badge variant="secondary">
   150→              {gender === "MALE"
   151→                ? "Male"
   152→                : gender === "FEMALE"
   153→                  ? "Female"
   154→                  : "Other"}
   155→            </Badge>
   156→          )}
   157→        </div>
   158→      )}
   159→
   160→      {persons.length === 0 ? (
   161→        <div className="py-12 text-center text-muted-foreground">
   162→          {search
   163→            ? `No results found for "${search}"`
   164→            : "No people in the family tree yet"}
   165→        </div>
   166→      ) : (
   167→        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
   168→          {persons.map((person) => (
