      await page.getByRole("button", { name: /save|create|add/i }).click();
      await expect(page.getByRole("dialog")).not.toBeVisible({ timeout: 5000 });

      // Wait for person to appear in list using more specific selector
      const personName = `Test Date${testCase.input.replace(/-/g, "")}`;
      await expect(page.getByRole("link", { name: new RegExp(personName, "i") })).toBeVisible({ timeout: 5000 });

