    await expect(page.getByRole("link", { name: /edit datetest/i })).toBeVisible({ timeout: 1000 });

    // Navigate to profile
    await page.getByRole("link", { name: /edit datetest/i }).first().click();

    // Edit the person
    await page.getByRole("button", { name: /edit/i }).click();

