    // Submit the form
    await page.getByRole("button", { name: /save|create|add/i }).click();

    // Wait for the dialog to close
    await expect(page.getByRole("dialog")).not.toBeVisible({ timeout: 2000 });

    // Search for the newly created person to navigate to their profile
    // (They may not be in the first page of results due to pagination)
    await peoplePage.searchFor("Jane TestDate");
    await page.waitForTimeout(500); // Wait for search debounce

    // Navigate to the person's profile to verify the date
    await expect(page.getByText("Jane TestDate")).toBeVisible({ timeout: 3000 });
    await page.getByText("Jane TestDate").first().click();

    // Verify the birthday displays as January 2, 1990
    await expect(page.getByText("January 2, 1990")).toBeVisible();
  });

  test("marriage anniversary remains consistent across timezones", async ({
    page,
