import { test, expect } from "@playwright/test";
import { LoginPage } from "./pages/LoginPage";
import { PeoplePage } from "./pages/PeoplePage";

test.describe("Date Handling - Timezone Independence", () => {
  test.beforeEach(async ({ page }) => {
    const loginPage = new LoginPage(page);
    await loginPage.goto();
    await loginPage.login("admin@family.local", "admin123");
    await expect(page).toHaveURL("/tree");
  });

  test("birthday entered as specific date displays consistently", async ({
    page,
  }) => {
    const peoplePage = new PeoplePage(page);
    await peoplePage.goto();

    await peoplePage.addPersonButton.click();
    await expect(page.getByRole("dialog")).toBeVisible();

    await page.getByLabel("First Name").fill("TestJane");
    await page.getByLabel("Last Name").fill("BirthdayCheck");
    await page.getByLabel("Date of Birth").fill("1990-01-02");

    await page.getByRole("button", { name: /save|create|add/i }).click();
    await page.waitForURL("/people", { timeout: 10000 });
    await page.waitForTimeout(500);

    const personLink = page.getByRole("link", { name: /TestJane BirthdayCheck/i }).first();
    await personLink.click();
    await page.waitForURL(/\/people\/[a-z0-9]+/, { timeout: 10000 });

    await expect(page.getByText("January 2, 1990")).toBeVisible({ timeout: 5000 });
  });

  test("marriage anniversary remains consistent across timezones", async ({
    page,
  }) => {
    const peoplePage = new PeoplePage(page);
    await peoplePage.goto();

    // Create first person
    await peoplePage.addPersonButton.click();
    await page.getByLabel("First Name").fill("TestJohn");
    await page.getByLabel("Last Name").fill("MarriageTest");
    await page.getByLabel("Date of Birth").fill("1985-06-15");
    await page.getByRole("button", { name: /save|create|add/i }).click();
    await page.waitForURL("/people", { timeout: 10000 });
    await page.waitForTimeout(500);

    // Create second person
    await peoplePage.goto();
    await peoplePage.addPersonButton.click();
    await page.getByLabel("First Name").fill("TestJaneM");
    await page.getByLabel("Last Name").fill("MarriageTest");
    await page.getByLabel("Date of Birth").fill("1987-08-20");
    await page.getByRole("button", { name: /save|create|add/i }).click();
    await page.waitForURL("/people", { timeout: 10000 });
    await page.waitForTimeout(500);

    // Navigate to first person
    await peoplePage.goto();
    const johnLink = page.getByRole("link", { name: /TestJohn MarriageTest/i }).first();
    await johnLink.click();
    await page.waitForURL(/\/people\/[a-z0-9]+/, { timeout: 10000 });

    // Add marriage relationship
    const addRelBtn = page.getByRole("button", { name: /add relationship/i });
    if (await addRelBtn.isVisible()) {
      await addRelBtn.click();
      await page.getByLabel(/person/i).selectOption({ label: /TestJaneM/ });
      await page.getByLabel(/relationship type/i).selectOption("SPOUSE");
      const marDateInput = page.getByLabel(/marriage date/i);
      if (await marDateInput.isVisible()) {
        await marDateInput.fill("2010-12-25");
      }
      await page.getByRole("button", { name: /save|add/i }).click();
      await page.waitForTimeout(1000);

      await expect(page.getByText("December 25, 2010")).toBeVisible({ timeout: 5000 });
    }
  });

  test("date input preserves exact date entered", async ({ page }) => {
    const peoplePage = new PeoplePage(page);
    await peoplePage.goto();

    const testDates = [
      { input: "2000-02-29", display: "February 29, 2000" },
      { input: "1999-12-31", display: "December 31, 1999" },
      { input: "2001-01-01", display: "January 1, 2001" },
      { input: "1985-07-04", display: "July 4, 1985" },
    ];

    for (const testCase of testDates) {
      await peoplePage.goto();
      await peoplePage.addPersonButton.click();
      const lastName = `DateTest${testCase.input.replace(/-/g, "")}`;
      await page.getByLabel("First Name").fill("TestDatePerson");
      await page.getByLabel("Last Name").fill(lastName);
      await page.getByLabel("Date of Birth").fill(testCase.input);

      await page.getByRole("button", { name: /save|create|add/i }).click();
      await page.waitForURL("/people", { timeout: 10000 });
      await page.waitForTimeout(500);

      const personLink = page.getByRole("link", { name: new RegExp(`TestDatePerson.*${lastName}`, "i") }).first();
      await personLink.click();
      await page.waitForURL(/\/people\/[a-z0-9]+/, { timeout: 10000 });

      await expect(page.getByText(testCase.display)).toBeVisible({ timeout: 5000 });
    }
  });

  test("date editing preserves timezone independence", async ({ page }) => {
    const peoplePage = new PeoplePage(page);
    await peoplePage.goto();

    await peoplePage.addPersonButton.click();
    await page.getByLabel("First Name").fill("TestEdit");
    await page.getByLabel("Last Name").fill("DatePerson");
    await page.getByLabel("Date of Birth").fill("1990-06-15");

    await page.getByRole("button", { name: /save|create|add/i }).click();
    await page.waitForURL("/people", { timeout: 10000 });
    await page.waitForTimeout(500);

    const personLink = page.getByRole("link", { name: /TestEdit DatePerson/i }).first();
    await personLink.click();
    await page.waitForURL(/\/people\/[a-z0-9]+/, { timeout: 10000 });

    const editBtn = page.getByRole("button", { name: /edit/i });
    if (await editBtn.isVisible()) {
      await editBtn.click();
      const dateInput = page.getByLabel("Date of Birth");
      await expect(dateInput).toHaveValue("1990-06-15");

      await dateInput.fill("1990-06-16");
      await page.getByRole("button", { name: /save|update/i }).click();
      await page.waitForTimeout(1000);

      await expect(page.getByText("June 16, 1990")).toBeVisible({ timeout: 5000 });
    }
  });

  test("death date handling maintains consistency", async ({ page }) => {
    const peoplePage = new PeoplePage(page);
    await peoplePage.goto();

    await peoplePage.addPersonButton.click();
    await page.getByLabel("First Name").fill("TestDeceased");
    await page.getByLabel("Last Name").fill("Person");
    await page.getByLabel("Date of Birth").fill("1920-03-15");

    await page.getByLabel("Living").uncheck();
    await page.getByLabel("Date of Passing").fill("2000-11-30");

    await page.getByRole("button", { name: /save|create|add/i }).click();
    await page.waitForURL("/people", { timeout: 10000 });
    await page.waitForTimeout(500);

    const personLink = page.getByRole("link", { name: /TestDeceased Person/i }).first();
    await personLink.click();
    await page.waitForURL(/\/people\/[a-z0-9]+/, { timeout: 10000 });

    await expect(page.getByText("March 15, 1920")).toBeVisible({ timeout: 5000 });
    await expect(page.getByText("November 30, 2000")).toBeVisible({ timeout: 5000 });
  });

  test("age calculation works correctly with date-only values", async ({
    page,
  }) => {
    const peoplePage = new PeoplePage(page);
    await peoplePage.goto();

    const currentYear = new Date().getFullYear();
    const birthYear = currentYear - 30;
    const birthDate = `${birthYear}-06-15`;

    await peoplePage.addPersonButton.click();
    await page.getByLabel("First Name").fill("TestAge");
    await page.getByLabel("Last Name").fill("Person");
    await page.getByLabel("Date of Birth").fill(birthDate);

    await page.getByRole("button", { name: /save|create|add/i }).click();
    await page.waitForURL("/people", { timeout: 10000 });
    await page.waitForTimeout(500);

    const personLink = page.getByRole("link", { name: /TestAge Person/i }).first();
    await personLink.click();
    await page.waitForURL(/\/people\/[a-z0-9]+/, { timeout: 10000 });

    await expect(page.locator("text=/(29|30|31) years old/")).toBeVisible({ timeout: 5000 });
  });

  test("form validation handles invalid dates gracefully", async ({ page }) => {
    const peoplePage = new PeoplePage(page);
    await peoplePage.goto();

    await peoplePage.addPersonButton.click();
    await page.getByLabel("First Name").fill("TestInvalid");
    await page.getByLabel("Last Name").fill("Date");

    const dateInput = page.getByLabel("Date of Birth");
    await dateInput.fill("invalid-date");

    const inputValue = await dateInput.inputValue();
    expect(inputValue === "" || inputValue === "invalid-date").toBe(true);

    await dateInput.fill("1990-06-15");
    await page.getByRole("button", { name: /save|create|add/i }).click();
    await page.waitForURL("/people", { timeout: 10000 });
    await page.waitForTimeout(500);

    await expect(page.getByRole("link", { name: /TestInvalid Date/i })).toBeVisible({ timeout: 5000 });
  });

  test("date display format is consistent across the application", async ({
    page,
  }) => {
    const peoplePage = new PeoplePage(page);
    await peoplePage.goto();

    await peoplePage.addPersonButton.click();
    await page.getByLabel("First Name").fill("TestFormat");
    await page.getByLabel("Last Name").fill("Test");
    await page.getByLabel("Date of Birth").fill("1985-12-25");

    await page.getByRole("button", { name: /save|create|add/i }).click();
    await page.waitForURL("/people", { timeout: 10000 });
    await page.waitForTimeout(500);

    const personLink = page.getByRole("link", { name: /TestFormat Test/i }).first();
    await personLink.click();
    await page.waitForURL(/\/people\/[a-z0-9]+/, { timeout: 10000 });

    await expect(page.getByText("December 25, 1985")).toBeVisible({ timeout: 5000 });

    const editBtn = page.getByRole("button", { name: /edit/i });
    if (await editBtn.isVisible()) {
      await editBtn.click();
      const dateInput = page.getByLabel("Date of Birth");
      await expect(dateInput).toHaveValue("1985-12-25");
    }
  });

  test("timezone changes do not affect stored dates", async ({ page }) => {
    const peoplePage = new PeoplePage(page);
    await peoplePage.goto();

    await peoplePage.addPersonButton.click();
    await page.getByLabel("First Name").fill("TestTimezone");
    await page.getByLabel("Last Name").fill("Test");
    await page.getByLabel("Date of Birth").fill("1990-01-02");

    await page.getByRole("button", { name: /save|create|add/i }).click();
    await page.waitForURL("/people", { timeout: 10000 });
    await page.waitForTimeout(500);

    const personLink = page.getByRole("link", { name: /TestTimezone Test/i }).first();
    await personLink.click();
    await page.waitForURL(/\/people\/[a-z0-9]+/, { timeout: 10000 });

    await expect(page.getByText("January 2, 1990")).toBeVisible({ timeout: 5000 });

    await page.reload();
    await page.waitForTimeout(1000);

    await expect(page.getByText("January 2, 1990")).toBeVisible({ timeout: 5000 });
  });
});

